from mcp.server.fastmcp import FastMCP

mcp = FastMCP("deploy-info")

@mcp.tool()
def rollout_status(service: str, env: str = "staging") -> str:
    """Return rollout state for a service. env is staging or prod."""
    state = get_rollout(service, env)  # read-only lookup
    return f"{service} in {env}: {state.phase}, {state.ready}/{state.desired} ready"

if __name__ == "__main__":
    mcp.run()  # stdio transport by default
